				}
				add_to_galactic_council = yes
			}
			random_playable_country = {
				limit = {
					is_galactic_community_member = yes
					is_part_of_galactic_council = no
					is_galactic_custodian = no
				}
				add_to_galactic_council = yes
			}
		}
		country_event = { id = emperor.1 }
	}
}

