	immediate = {
		remove_global_flag = imperial_charter_granted
		every_galaxy_planet = {
			limit = { has_carrier_flag = imp_concession_port }
			remove_carrier_flag = imp_concession_port
		}
		event_target:gal_emperor = {
			set_variable = {
				which = "imp_concession_ports"
				value = 0
			}
			add_imp_concession_ports_0 = yes
		}
	}
}

country_event = {
	id = emperor.65
	hide_window = yes

	is_triggered_only = yes

	immediate = {
		if = {
			limit = {
				check_variable = {
					which = imp_concession_ports
					value < 1
				}
			}
			add_imp_concession_ports_0 = yes
		}
		else_if = {
			limit = {
				check_variable = {
					which = imp_concession_ports
					value >= 1
				}
				check_variable = {
					which = imp_concession_ports
					value <= 2
				}
			}
			add_imp_concession_ports = { MODIFIER = imp_concession_ports_1 }
		}
		else_if = {
			limit = {
				check_variable = {
					which = imp_concession_ports
					value >= 3
				}
				check_variable = {
					which = imp_concession_ports
					value <= 4
				}
			}
			add_imp_concession_ports = { MODIFIER = imp_concession_ports_2 }
		}
		else_if = {
			limit = {
				check_variable = {
					which = imp_concession_ports
					value >= 5
				}
